import 'package:flutter/material.dart';
import 'package:qr_flutter/qr_flutter.dart';
import 'api.dart';
class MfaSetupScreen extends StatefulWidget{const MfaSetupScreen({super.key});@override State<MfaSetupScreen> createState()=>_State();}
class _State extends State<MfaSetupScreen>{String? uri,msg;final code=TextEditingController();Future<void> setup()async{try{final u=await adminApi.mfaSetup();setState(()=>uri=u);}catch(_){setState(()=>msg='MFA setup could not be started.');}}Future<void> confirm()async{try{await adminApi.mfaConfirm(code.text.trim());setState(()=>msg='Agent MFA is enabled.');}catch(_){setState(()=>msg='Invalid TOTP code.');}}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('Agent MFA',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Agent sessions cannot be created without a valid TOTP code.'),const SizedBox(height:16),ElevatedButton(onPressed:setup,child:const Text('Generate / rotate enrollment')),if(uri!=null)...[const SizedBox(height:12),Center(child:QrImageView(data:uri!,size:220)),SelectableText(uri!),TextField(controller:code,keyboardType:TextInputType.number,maxLength:6,decoration:const InputDecoration(labelText:'6-digit authenticator code')),ElevatedButton(onPressed:confirm,child:const Text('Confirm MFA'))],if(msg!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(msg!))]);}
